/**
 * Pure TypeScript Declarative Dynamic UI Renderer
 * 
 * Safely compiles JSON dynamic UI schemas generated by prompt-in-a-box agent loops
 * or defined declaratively in `prompt.md` into visually stunning, interactive, responsive UI views.
 * Supports theme selection, component types, input form tracking, execution routing,
 * and live-bound Action History with per-item and batch undo.
 */

import { listActionHistory, type ActionHistoryEntry } from './action-history';
import {
  printAgentLogToConsole,
  getLiveLogs,
  clearLiveLogs,
  type AgentLogEvent,
  type RunLiveStatus,
} from './logger';

export interface UIComponent {
  type:
    | 'header'
    | 'text'
    | 'button'
    | 'alert'
    | 'list'
    | 'input'
    | 'metrics'
    | 'action-list'
    | 'action-history'
    | 'divider';
  id?: string;
  text?: string;
  intent?: 'info' | 'success' | 'warning' | 'danger';
  action?: 'trigger-run' | 'chrome-api' | 'undo-last' | 'undo-action' | 'open-studio' | 'none';
  actionId?: string;
  apiMethod?: string;
  apiArgs?: any[];
  placeholder?: string;
  items?: string[];
  payload?: any;
  limit?: number;
  showUndoAll?: boolean;
  undoAllLabel?: string;
  emptyText?: string;
  metrics?: Array<{ label: string; value: string; subvalue?: string }>;
  actions?: Array<{
    id?: string;
    label: string;
    detail?: string;
    timestamp?: string;
    undoable?: boolean;
    undone?: boolean;
  }>;
}

export interface UISchema {
  title: string;
  theme?: 'default' | 'glassmorphic' | 'compact';
  components: UIComponent[];
}

const DYNAMIC_UI_KEY = '__pib_dynamic_ui';

/**
 * Extracts a declarative UI specification block from a prompt markdown file.
 * Matches ```ui ... ``` or ```json ui ... ``` or ```json:ui ... ```.
 */
export function extractUIBlockFromPrompt(markdown: string): UISchema | null {
  if (!markdown) return null;
  const match = markdown.match(/```(?:ui|json\s+ui|json:ui)\s*\n([\s\S]*?)\n```/i);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[1]);
    if (parsed && typeof parsed === 'object' && Array.isArray(parsed.components)) {
      return parsed as UISchema;
    }
  } catch (err) {
    console.warn('Failed to parse declarative UI block from prompt.md:', err);
  }
  return null;
}

/**
 * Fetches prompt.md from the extension bundle and extracts the declarative UI schema, if present.
 */
export async function loadPromptUIBlock(): Promise<UISchema | null> {
  try {
    const stored = await chrome.storage.local.get('studioLiveOverride');
    const override = stored.studioLiveOverride as { enabled?: boolean; prompt?: string } | undefined;
    if (override?.enabled && typeof override.prompt === 'string' && override.prompt.trim().length > 0) {
      const liveSchema = extractUIBlockFromPrompt(override.prompt);
      if (liveSchema) return liveSchema;
    }
  } catch {
    // fallback to prompt.md
  }

  try {
    const url = chrome.runtime.getURL('prompt.md');
    const res = await fetch(url);
    if (!res.ok) return null;
    const text = await res.text();
    return extractUIBlockFromPrompt(text);
  } catch {
    return null;
  }
}

export class UIRenderer {
  private container: HTMLElement;
  private formValues: Record<string, any> = {};
  private viewName: string;
  private listeningForHistory = false;
  private listeningForLogs = false;
  private logs: AgentLogEvent[] = [];
  private liveStatus: RunLiveStatus = {
    active: false,
    runId: '',
    statusText: 'Idle',
    updatedAt: Date.now(),
  };
  private consoleDrawerEl: HTMLElement | null = null;
  private consoleLogListEl: HTMLElement | null = null;
  private consoleStreamingBoxEl: HTMLElement | null = null;
  private consoleStatusTextEl: HTMLElement | null = null;
  private consoleDotEl: HTMLElement | null = null;
  private consoleCountBadgeEl: HTMLElement | null = null;

  constructor(container: HTMLElement, viewName: string) {
    this.container = container;
    this.viewName = viewName;
    this.setupHistoryListener();
    this.setupLogListener();
  }

  private setupLogListener(): void {
    if (this.listeningForLogs) return;
    this.listeningForLogs = true;
    try {
      chrome.runtime.onMessage.addListener((msg) => {
        if (msg?.type === 'agent-log' && msg.event) {
          // Print directly to console for DevTools inspect
          printAgentLogToConsole(msg.event);

          this.appendLogEntry(msg.event);

          if (msg.status) {
            this.updateLiveStatus(msg.status);
          }

          if (msg.event.channel === 'run-start' && this.consoleDrawerEl) {
            this.consoleDrawerEl.classList.add('expanded');
          }
        } else if (msg?.type === 'agent-stream-delta') {
          if (this.consoleStreamingBoxEl) {
            this.consoleStreamingBoxEl.classList.add('visible');
            const prefix = msg.kind === 'reasoning' ? '🧠 Thinking: ' : '✍️ Output: ';
            this.consoleStreamingBoxEl.textContent = prefix + msg.fullText;
            this.consoleStreamingBoxEl.scrollTop = this.consoleStreamingBoxEl.scrollHeight;
          }
        }
      });
    } catch {
      // Ignored
    }
  }

  private updateLiveStatus(status: RunLiveStatus): void {
    this.liveStatus = status;
    if (this.consoleStatusTextEl) {
      this.consoleStatusTextEl.textContent = status.statusText || (status.active ? 'Running...' : 'Idle');
    }
    if (this.consoleDotEl) {
      if (status.active) {
        this.consoleDotEl.classList.add('active');
      } else {
        this.consoleDotEl.classList.remove('active');
      }
    }
  }

  private setupHistoryListener(): void {
    if (this.listeningForHistory) return;
    this.listeningForHistory = true;
    try {
      chrome.runtime.onMessage.addListener((msg) => {
        if (msg?.type === 'action-history-updated') {
          const historyContainers = this.container.querySelectorAll('.ui-action-history-container');
          for (const el of Array.from(historyContainers)) {
            const compData = (el as any).__compData as UIComponent | undefined;
            if (compData) {
              void this.populateActionHistory(el as HTMLElement, compData);
            }
          }
        }
      });
    } catch {
      // Ignored
    }
  }

  /**
   * Loads the saved UI specification from chrome storage or falls back to prompt.md declarative block.
   */
  async loadAndRender(): Promise<void> {
    const data = await chrome.storage.local.get(DYNAMIC_UI_KEY);
    let spec = data[DYNAMIC_UI_KEY] as UISchema | undefined;
    const promptSpec = await loadPromptUIBlock();

    if (!spec) {
      if (promptSpec) {
        spec = promptSpec;
      } else {
        this.renderWelcomeState();
        return;
      }
    } else if (promptSpec) {
      // If prompt.md defines an action-history component that is absent from the runtime spec, preserve it
      const hasActionHistory = spec.components.some((c) => c.type === 'action-history');
      const promptActionHistory = promptSpec.components.find((c) => c.type === 'action-history');
      if (!hasActionHistory && promptActionHistory) {
        spec = {
          ...spec,
          components: [...spec.components, promptActionHistory],
        };
      }
    }

    this.render(spec);

    try {
      const { logs, status } = await getLiveLogs();
      this.logs = logs || [];
      if (status) this.liveStatus = status;
      this.populateLiveLogs();
      if (this.liveStatus) this.updateLiveStatus(this.liveStatus);
    } catch {
      // ignore
    }
  }

  /**
   * Renders a fallback welcoming view if no dynamic UI has been posted yet.
   */
  private renderWelcomeState(): void {
    this.container.innerHTML = `
      <div class="welcome-container">
        <div class="welcome-icon-box">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <rect x="3" y="11" width="18" height="10" rx="2"></rect>
            <circle cx="12" cy="5" r="2"></circle>
            <path d="M12 7v4"></path>
            <line x1="8" y1="16" x2="8" y2="16"></line>
            <line x1="16" y1="16" x2="16" y2="16"></line>
          </svg>
        </div>
        <h3>Agent Dynamic View</h3>
        <p>No active runtime interface has been posted by the agent yet.</p>
        <button id="triggerWelcomeRun" class="ui-btn btn-intent-info">Initialize Agent</button>
      </div>
    `;
    
    const btn = this.container.querySelector('#triggerWelcomeRun');
    if (btn) {
      btn.addEventListener('click', async () => {
        const text = btn.textContent;
        btn.textContent = 'Initializing...';
        (btn as HTMLButtonElement).disabled = true;
        try {
          await chrome.runtime.sendMessage({
            type: 'ui-opened',
            view: this.viewName
          });
        } finally {
          btn.textContent = text;
          (btn as HTMLButtonElement).disabled = false;
        }
      });
    }

    this.container.appendChild(this.createLiveConsoleDrawer());
  }

  /**
   * Main render entry point. Builds DOM nodes safely to prevent XSS.
   */
  render(spec: UISchema): void {
    this.container.innerHTML = '';
    this.formValues = {};

    // Apply overall theme classes to container
    this.container.className = `ui-container theme-${spec.theme || 'default'}`;

    // 1. Render View Title
    const titleEl = document.createElement('h1');
    titleEl.className = 'ui-title';
    titleEl.textContent = spec.title;
    this.container.appendChild(titleEl);

    // 2. Render all components
    const componentWrapper = document.createElement('div');
    componentWrapper.className = 'ui-components';

    for (const comp of spec.components) {
      const el = this.createComponent(comp);
      if (el) {
        componentWrapper.appendChild(el);
      }
    }

    this.container.appendChild(componentWrapper);

    // 3. Render Live Console Drawer
    this.container.appendChild(this.createLiveConsoleDrawer());
  }

  /**
   * Factory function that creates individual component nodes.
   */
  private createComponent(comp: UIComponent): HTMLElement | null {
    switch (comp.type) {
      case 'header': {
        const el = document.createElement('h2');
        el.className = 'ui-header-element';
        el.textContent = comp.text || '';
        return el;
      }

      case 'text': {
        const el = document.createElement('p');
        el.className = 'ui-text-element';
        el.textContent = comp.text || '';
        return el;
      }

      case 'divider': {
        const hr = document.createElement('hr');
        hr.className = 'ui-divider';
        return hr;
      }

      case 'alert': {
        const el = document.createElement('div');
        el.className = `ui-alert intent-${comp.intent || 'info'}`;
        
        // Add indicator icon
        const iconEl = document.createElement('span');
        iconEl.className = 'alert-icon';
        iconEl.innerHTML = this.getAlertIcon(comp.intent || 'info');
        el.appendChild(iconEl);

        const textEl = document.createElement('span');
        textEl.className = 'alert-text';
        textEl.textContent = comp.text || '';
        el.appendChild(textEl);

        return el;
      }

      case 'list': {
        if (!comp.items || comp.items.length === 0) return null;
        const el = document.createElement('ul');
        el.className = 'ui-list';
        for (const item of comp.items) {
          const li = document.createElement('li');
          li.textContent = item;
          el.appendChild(li);
        }
        return el;
      }

      case 'metrics': {
        if (!comp.metrics || comp.metrics.length === 0) return null;
        const grid = document.createElement('div');
        grid.className = 'ui-metrics-grid';
        for (const m of comp.metrics) {
          const card = document.createElement('div');
          card.className = 'ui-metric-card';

          const label = document.createElement('div');
          label.className = 'ui-metric-label';
          label.textContent = m.label;
          card.appendChild(label);

          const val = document.createElement('div');
          val.className = 'ui-metric-value';
          val.textContent = m.value;
          card.appendChild(val);

          if (m.subvalue) {
            const sub = document.createElement('div');
            sub.className = 'ui-metric-subvalue';
            sub.textContent = m.subvalue;
            card.appendChild(sub);
          }
          grid.appendChild(card);
        }
        return grid;
      }

      case 'input': {
        if (!comp.id) return null;
        const wrapper = document.createElement('div');
        wrapper.className = 'ui-input-wrapper';

        const label = document.createElement('label');
        label.setAttribute('for', comp.id);
        label.textContent = comp.text || '';
        wrapper.appendChild(label);

        const input = document.createElement('input');
        input.type = 'text';
        input.id = comp.id;
        input.placeholder = comp.placeholder || '';
        input.className = 'ui-input-field';

        // Track state changes dynamically
        input.addEventListener('input', () => {
          this.formValues[comp.id!] = input.value;
        });

        wrapper.appendChild(input);
        return wrapper;
      }

      case 'action-list': {
        const wrapper = document.createElement('div');
        wrapper.className = 'ui-action-list-wrapper';
        if (comp.text) {
          const h = document.createElement('h3');
          h.className = 'ui-section-header';
          h.textContent = comp.text;
          wrapper.appendChild(h);
        }
        const list = document.createElement('div');
        list.className = 'ui-action-list';

        const actions = comp.actions || [];
        if (actions.length === 0) {
          const empty = document.createElement('div');
          empty.className = 'ui-empty-state';
          empty.textContent = comp.emptyText || 'No actions recorded yet.';
          list.appendChild(empty);
        } else {
          for (const item of actions) {
            const row = document.createElement('div');
            row.className = `ui-action-row ${item.undone ? 'action-undone' : ''}`;

            const info = document.createElement('div');
            info.className = 'ui-action-info';

            const title = document.createElement('div');
            title.className = 'ui-action-label';
            title.textContent = item.label;
            info.appendChild(title);

            if (item.detail) {
              const detail = document.createElement('div');
              detail.className = 'ui-action-detail';
              detail.textContent = item.detail;
              info.appendChild(detail);
            }

            row.appendChild(info);

            if (item.undone) {
              const pill = document.createElement('span');
              pill.className = 'ui-reverted-pill';
              pill.textContent = 'Reverted';
              row.appendChild(pill);
            } else if (item.undoable !== false && item.id) {
              const undoBtn = document.createElement('button');
              undoBtn.className = 'ui-action-undo-btn';
              undoBtn.textContent = 'Undo';
              undoBtn.addEventListener('click', async () => {
                undoBtn.disabled = true;
                undoBtn.textContent = 'Undoing...';
                await chrome.runtime.sendMessage({ type: 'undo-action', actionId: item.id });
                row.classList.add('action-undone');
                const pill = document.createElement('span');
                pill.className = 'ui-reverted-pill';
                pill.textContent = 'Reverted';
                undoBtn.replaceWith(pill);
              });
              row.appendChild(undoBtn);
            }
            list.appendChild(row);
          }
        }
        wrapper.appendChild(list);
        return wrapper;
      }

      case 'action-history': {
        const wrapper = document.createElement('div');
        wrapper.className = 'ui-action-history-container';
        (wrapper as any).__compData = comp;
        void this.populateActionHistory(wrapper, comp);
        return wrapper;
      }

      case 'button': {
        const el = document.createElement('button');
        el.className = `ui-btn btn-intent-${comp.intent || 'info'}`;
        el.textContent = comp.text || 'Button';

        if (comp.id) {
          el.setAttribute('id', comp.id);
        }

        // Click interaction logic
        el.addEventListener('click', async () => {
          el.classList.add('btn-loading');
          const originalText = el.textContent;
          el.textContent = 'Processing...';
          el.disabled = true;

          try {
            if (comp.action === 'open-studio') {
              await chrome.tabs.create({ url: chrome.runtime.getURL('dist/studio.html') });
            } else if (comp.action === 'undo-last') {
              await chrome.runtime.sendMessage({ type: 'action-toast-undo' });
            } else if (comp.action === 'undo-action' && comp.actionId) {
              await chrome.runtime.sendMessage({ type: 'undo-action', actionId: comp.actionId });
            } else if (comp.action === 'chrome-api' && comp.apiMethod) {
              const parsedArgs = (comp.apiArgs || []).map((arg) => {
                if (typeof arg === 'string') {
                  try {
                    return JSON.parse(arg);
                  } catch {
                    return arg;
                  }
                }
                return arg;
              });
              await this.executeChromeAPI(comp.apiMethod, parsedArgs);
            } else if (comp.action === 'trigger-run') {
              if (this.consoleDrawerEl) {
                this.consoleDrawerEl.classList.add('expanded');
              }
              this.updateLiveStatus({
                active: true,
                runId: '',
                statusText: 'Triggering agent run...',
                updatedAt: Date.now(),
              });
              // Combine default payload with dynamic inputs
              const payload = {
                ...comp.payload,
                formValues: this.formValues
              };
              await chrome.runtime.sendMessage({
                type: 'ui-interaction',
                componentId: comp.id || 'unnamed',
                action: comp.action,
                payload
              });
            }
          } catch (err) {
            console.error('Interaction execution error:', err);
          } finally {
            el.classList.remove('btn-loading');
            el.textContent = originalText;
            el.disabled = false;
          }
        });

        return el;
      }

      default:
        return null;
    }
  }

  /**
   * Populates a live action-history container with recent actions from chrome.storage.local
   * and renders both a prominent Undo button and individual per-action undo buttons.
   */
  private async populateActionHistory(container: HTMLElement, comp: UIComponent): Promise<void> {
    const history = await listActionHistory(comp.limit ?? 15);
    container.innerHTML = '';

    const nonUndoneCount = history.filter((e) => !e.undone).length;

    // 1. Prominent Undo Banner / Button Card (if enabled)
    if (comp.showUndoAll !== false) {
      const banner = document.createElement('div');
      banner.className = 'ui-undo-banner';

      const bannerContent = document.createElement('div');
      bannerContent.className = 'ui-undo-banner-content';

      const iconSvg = document.createElement('span');
      iconSvg.className = 'ui-undo-icon';
      iconSvg.innerHTML = `
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="1 4 1 10 7 10"></polyline>
          <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"></path>
        </svg>
      `;
      bannerContent.appendChild(iconSvg);

      const bannerText = document.createElement('div');
      bannerText.className = 'ui-undo-banner-text';

      const bannerTitle = document.createElement('div');
      bannerTitle.className = 'ui-undo-banner-title';
      bannerTitle.textContent = comp.undoAllLabel || 'Undo Last Sort';
      bannerText.appendChild(bannerTitle);

      const bannerSub = document.createElement('div');
      bannerSub.className = 'ui-undo-banner-sub';
      bannerSub.textContent =
        nonUndoneCount > 0
          ? `${nonUndoneCount} reversible action${nonUndoneCount === 1 ? '' : 's'}`
          : 'All actions reverted / no recent changes';
      bannerText.appendChild(bannerSub);

      bannerContent.appendChild(bannerText);
      banner.appendChild(bannerContent);

      const undoAllBtn = document.createElement('button');
      undoAllBtn.className = 'ui-btn btn-undo-all btn-intent-warning';
      undoAllBtn.textContent = 'Undo All';
      if (nonUndoneCount === 0) {
        undoAllBtn.disabled = true;
        undoAllBtn.classList.add('btn-disabled');
      }

      undoAllBtn.addEventListener('click', async () => {
        undoAllBtn.disabled = true;
        const oldText = undoAllBtn.textContent;
        undoAllBtn.textContent = 'Reverting...';
        try {
          await chrome.runtime.sendMessage({ type: 'action-toast-undo' });
          await this.populateActionHistory(container, comp);
        } catch (err) {
          console.error('Failed to undo all:', err);
        } finally {
          undoAllBtn.textContent = oldText;
          undoAllBtn.disabled = false;
        }
      });

      banner.appendChild(undoAllBtn);
      container.appendChild(banner);
    }

    // 2. Recent Actions Section Header
    const sectionHeader = document.createElement('div');
    sectionHeader.className = 'ui-section-header-row';

    const headerTitle = document.createElement('h3');
    headerTitle.className = 'ui-section-header';
    headerTitle.textContent = comp.text || 'Recent Actions';
    sectionHeader.appendChild(headerTitle);

    const countBadge = document.createElement('span');
    countBadge.className = 'ui-count-badge';
    countBadge.textContent = `${history.length}`;
    sectionHeader.appendChild(countBadge);

    container.appendChild(sectionHeader);

    // 3. Actions List
    const listEl = document.createElement('div');
    listEl.className = 'ui-action-list';

    if (history.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'ui-empty-state';
      empty.textContent = comp.emptyText || 'No tab sorting or browser actions recorded yet.';
      listEl.appendChild(empty);
    } else {
      for (const entry of history) {
        const row = this.createActionRow(entry, container, comp);
        listEl.appendChild(row);
      }
    }

    container.appendChild(listEl);
  }

  /**
   * Helper that builds a single action row with label, details, relative timestamp,
   * tool badge, and per-action Undo button.
   */
  private createActionRow(
    entry: ActionHistoryEntry,
    parentContainer: HTMLElement,
    comp: UIComponent,
  ): HTMLElement {
    const row = document.createElement('div');
    row.className = `ui-action-row ${entry.undone ? 'action-undone' : ''}`;

    const leftCol = document.createElement('div');
    leftCol.className = 'ui-action-info';

    const topMeta = document.createElement('div');
    topMeta.className = 'ui-action-meta-top';

    const toolBadge = document.createElement('span');
    toolBadge.className = `ui-tool-badge tool-${entry.toolName.replace(/_/g, '-')}`;
    toolBadge.textContent = entry.toolName;
    topMeta.appendChild(toolBadge);

    const timeEl = document.createElement('span');
    timeEl.className = 'ui-action-time';
    timeEl.textContent = this.formatRelativeTime(entry.timestamp);
    topMeta.appendChild(timeEl);

    leftCol.appendChild(topMeta);

    const labelEl = document.createElement('div');
    labelEl.className = 'ui-action-label';
    labelEl.textContent = entry.label;
    leftCol.appendChild(labelEl);

    if (entry.detail) {
      const detailEl = document.createElement('div');
      detailEl.className = 'ui-action-detail';
      detailEl.textContent = entry.detail;
      leftCol.appendChild(detailEl);
    }

    row.appendChild(leftCol);

    const rightCol = document.createElement('div');
    rightCol.className = 'ui-action-actions';

    if (entry.undone) {
      const pill = document.createElement('span');
      pill.className = 'ui-reverted-pill';
      pill.textContent = 'Reverted';
      rightCol.appendChild(pill);
    } else {
      const undoBtn = document.createElement('button');
      undoBtn.className = 'ui-action-undo-btn';
      undoBtn.textContent = 'Undo';
      undoBtn.setAttribute('title', 'Revert this action');

      undoBtn.addEventListener('click', async () => {
        undoBtn.disabled = true;
        undoBtn.textContent = 'Undoing...';
        try {
          await chrome.runtime.sendMessage({ type: 'undo-action', actionId: entry.id });
          await this.populateActionHistory(parentContainer, comp);
        } catch (err) {
          console.error('Failed to undo action:', err);
          undoBtn.disabled = false;
          undoBtn.textContent = 'Undo';
        }
      });

      rightCol.appendChild(undoBtn);
    }

    row.appendChild(rightCol);
    return row;
  }

  /**
   * Helper that formats a timestamp into relative time ("just now", "2m ago", "1h ago").
   */
  private formatRelativeTime(ts: number): string {
    const diffSec = Math.floor((Date.now() - ts) / 1000);
    if (diffSec < 10) return 'just now';
    if (diffSec < 60) return `${diffSec}s ago`;
    const diffMin = Math.floor(diffSec / 60);
    if (diffMin < 60) return `${diffMin}m ago`;
    const diffHours = Math.floor(diffMin / 60);
    if (diffHours < 24) return `${diffHours}h ago`;
    return `${Math.floor(diffHours / 24)}d ago`;
  }

  /**
   * Runs direct Chrome API calls safely.
   */
  private async executeChromeAPI(methodName: string, args: any[]): Promise<void> {
    const parts = methodName.split('.');
    let api: any = chrome;
    
    for (const part of parts) {
      if (!api[part]) {
        throw new Error(`Chrome API chrome.${methodName} not found.`);
      }
      api = api[part];
    }
    
    if (typeof api !== 'function') {
      throw new Error(`chrome.${methodName} is not a function.`);
    }

    return new Promise((resolve, reject) => {
      try {
        api(...args, (result: any) => {
          if (chrome.runtime.lastError) {
            reject(new Error(chrome.runtime.lastError.message));
          } else {
            resolve(result);
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  /**
   * Dynamic SVG icon builder depending on warning/success intent.
   */
  private getAlertIcon(intent: string): string {
    switch (intent) {
      case 'success':
        return '<svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd" /></svg>';
      case 'warning':
        return '<svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clip-rule="evenodd" /></svg>';
      case 'danger':
        return '<svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L10 8.586 8.707 7.293z" clip-rule="evenodd" /></svg>';
      default:
        return '<svg viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd" /></svg>';
    }
  }

  // ─── Live Console Drawer Construction ───────────────────────────────

  private createLiveConsoleDrawer(): HTMLElement {
    const drawer = document.createElement('div');
    drawer.className = 'ui-live-console-drawer';
    this.consoleDrawerEl = drawer;

    const header = document.createElement('div');
    header.className = 'ui-console-header';

    const left = document.createElement('div');
    left.className = 'ui-console-status-left';

    const dot = document.createElement('span');
    dot.className = `ui-console-dot ${this.liveStatus.active ? 'active' : ''}`;
    this.consoleDotEl = dot;
    left.appendChild(dot);

    const statusText = document.createElement('span');
    statusText.className = 'ui-console-status-text';
    statusText.textContent = this.liveStatus.statusText || 'Idle';
    this.consoleStatusTextEl = statusText;
    left.appendChild(statusText);

    const countBadge = document.createElement('span');
    countBadge.className = 'ui-console-count-badge';
    countBadge.textContent = `${this.logs.length} logs`;
    this.consoleCountBadgeEl = countBadge;
    left.appendChild(countBadge);

    header.appendChild(left);

    const right = document.createElement('div');
    right.className = 'ui-console-header-actions';

    const clearBtn = document.createElement('button');
    clearBtn.className = 'ui-console-btn';
    clearBtn.textContent = 'Clear';
    clearBtn.addEventListener('click', async (e) => {
      e.stopPropagation();
      await clearLiveLogs();
      this.logs = [];
      if (this.consoleLogListEl) this.consoleLogListEl.innerHTML = '';
      if (this.consoleStreamingBoxEl) {
        this.consoleStreamingBoxEl.textContent = '';
        this.consoleStreamingBoxEl.classList.remove('visible');
      }
      if (this.consoleCountBadgeEl) this.consoleCountBadgeEl.textContent = '0 logs';
    });
    right.appendChild(clearBtn);

    const toggleBtn = document.createElement('button');
    toggleBtn.className = 'ui-console-btn';
    toggleBtn.textContent = 'Logs ▾';
    right.appendChild(toggleBtn);

    header.appendChild(right);

    header.addEventListener('click', () => {
      drawer.classList.toggle('expanded');
    });

    drawer.appendChild(header);

    const body = document.createElement('div');
    body.className = 'ui-console-body';

    const streamingBox = document.createElement('div');
    streamingBox.className = 'ui-console-streaming-box';
    this.consoleStreamingBoxEl = streamingBox;
    body.appendChild(streamingBox);

    const logList = document.createElement('div');
    logList.className = 'ui-console-log-list';
    this.consoleLogListEl = logList;
    body.appendChild(logList);

    drawer.appendChild(body);

    this.populateLiveLogs();

    return drawer;
  }

  private appendLogEntry(ev: AgentLogEvent): void {
    this.logs.push(ev);
    if (this.logs.length > 100) this.logs.shift();
    if (this.consoleCountBadgeEl) {
      this.consoleCountBadgeEl.textContent = `${this.logs.length} log${this.logs.length === 1 ? '' : 's'}`;
    }

    if (!this.consoleLogListEl) return;

    const row = this.createLogRow(ev);
    this.consoleLogListEl.appendChild(row);
    this.consoleLogListEl.scrollTop = this.consoleLogListEl.scrollHeight;

    if (ev.channel === 'step-start' || ev.channel === 'tool-call' || ev.channel === 'run-complete') {
      if (this.consoleStreamingBoxEl) {
        this.consoleStreamingBoxEl.textContent = '';
        this.consoleStreamingBoxEl.classList.remove('visible');
      }
    }
  }

  private populateLiveLogs(): void {
    if (!this.consoleLogListEl) return;
    this.consoleLogListEl.innerHTML = '';
    for (const ev of this.logs) {
      this.consoleLogListEl.appendChild(this.createLogRow(ev));
    }
    this.consoleLogListEl.scrollTop = this.consoleLogListEl.scrollHeight;
    if (this.consoleCountBadgeEl) {
      this.consoleCountBadgeEl.textContent = `${this.logs.length} log${this.logs.length === 1 ? '' : 's'}`;
    }
  }

  private createLogRow(ev: AgentLogEvent): HTMLElement {
    const item = document.createElement('div');
    item.className = 'ui-console-log-item';

    const meta = document.createElement('div');
    meta.className = 'ui-console-log-meta';

    const badge = document.createElement('span');
    badge.className = `ui-channel-badge ${ev.channel}`;
    badge.textContent = ev.channel;
    meta.appendChild(badge);

    if (ev.step !== undefined) {
      const stepSpan = document.createElement('span');
      stepSpan.className = 'ui-console-log-step';
      stepSpan.textContent = `[s${ev.step + 1}]`;
      meta.appendChild(stepSpan);
    }

    const timeSpan = document.createElement('span');
    timeSpan.className = 'ui-console-log-time';
    timeSpan.textContent = new Date(ev.timestamp).toLocaleTimeString();
    meta.appendChild(timeSpan);

    if (ev.durationMs !== undefined) {
      const dur = document.createElement('span');
      dur.className = 'ui-console-log-time';
      dur.textContent = `${ev.durationMs}ms`;
      meta.appendChild(dur);
    }

    item.appendChild(meta);

    const title = document.createElement('div');
    title.className = 'ui-console-log-title';
    title.textContent = ev.title;
    item.appendChild(title);

    if (ev.body || ev.data !== undefined) {
      const details = document.createElement('details');
      details.className = 'ui-console-log-details';

      const summary = document.createElement('summary');
      summary.textContent = ev.body ? 'View Details' : 'View Payload';
      details.appendChild(summary);

      const pre = document.createElement('pre');
      pre.textContent = ev.body
        ? ev.body + (ev.data !== undefined ? '\n\n' + JSON.stringify(ev.data, null, 2) : '')
        : JSON.stringify(ev.data, null, 2);
      details.appendChild(pre);

      item.appendChild(details);
    }

    return item;
  }
}
